// CS2 weapon numbers, shared by the viewmodel (weapons/viewmodel.js), the buy commands (app/buy.js), replays and the
// co-op server's shot checks (server/coop-check.js), so a client can't claim more than the gun does.
// Guns: weapons-cs2.js, generated by `lasers-bake --weapons` from scripts/weapons.vdata (m_nDamage, m_flCycleTime,
// m_iMaxClip1, reserve = m_nPrimaryReserveAmmoMax clips, m_flDeployDuration, m_bIsFullAuto, m_flRange, m_flMaxSpeed,
// reload = m_flDisallowAttackAfterReloadStartDuration, m_nPrice) and each viewmodel's draw / reload clip sounds.
// Reserve stays full: ZE servers run CS2Fixes cs2f_infinite_reserve_ammo 1.
// Knife (CSKnife::SwingOrStab): slash refires 0.4 s after a miss, 40 damage on the first swing and 25 on a
// follow-up (a swing within 0.4 s of the refire time); stab 65, refires 1.0 s. Range 48 slash, 32 stab.
import { CS2_GUNS } from './weapons-cs2.js';

// CS2Fixes' names and buy aliases (src/utils/weapon.cpp s_WeaponMap), plus the short ones people type
// (m4, m4a1_s, ...). An alias wins over a bare class name: `m4a1` is the M4A1-S (CS2Fixes), `weapon_m4a1` the M4A4.
const CS2FIXES = {
  weapon_ak47: ['AK-47', ['ak47', 'ak']],
  weapon_aug: ['AUG', ['aug']],
  weapon_awp: ['AWP', ['awp']],
  weapon_famas: ['Famas', ['famas']],
  weapon_g3sg1: ['G3SG1', ['g3sg1']],
  weapon_galilar: ['Galil AR', ['galilar', 'galil']],
  weapon_m249: ['M249', ['m249']],
  weapon_m4a1: ['M4A4', ['m4a4', 'm4']],
  weapon_mac10: ['MAC-10', ['mac10', 'mac']],
  weapon_p90: ['P90', ['p90']],
  weapon_mp5sd: ['MP5-SD', ['mp5sd', 'mp5']],
  weapon_ump45: ['UMP-45', ['ump45', 'ump']],
  weapon_bizon: ['PP-Bizon', ['bizon', 'ppbizon', 'pp-bizon']],
  weapon_negev: ['Negev', ['negev']],
  weapon_mp7: ['MP7', ['mp7']],
  weapon_mp9: ['MP9', ['mp9']],
  weapon_scar20: ['SCAR-20', ['scar20', 'scar']],
  weapon_sg556: ['SG 553', ['sg553']],
  weapon_ssg08: ['SSG 08', ['ssg08', 'ssg']],
  weapon_m4a1_silencer: ['M4A1-S', ['m4a1-s', 'm4a1', 'm4a1_s', 'm4a1s']],
};

const freezeDeep = (o) => { for (const v of Object.values(o)) if (v && typeof v === 'object') freezeDeep(v); return Object.freeze(o); };

// vdata name -> { name, label, aliases, chassis, damage, cycle, clip, reserve, deploy, fullAuto, range, maxSpeed, reload,
// price, fireSound, drawSounds, reloadSounds }
export const GUNS = freezeDeep(Object.fromEntries(Object.entries(CS2_GUNS).map(([name, g]) => {
  const [label, aliases] = CS2FIXES[name] || [name.replace(/^weapon_/, ''), []];
  return [name, { ...g, name, label, aliases, icon: name.replace(/^weapon_/, '') }];
})));
// A stable order (replays store a gun as its index here: append only)
export const GUN_IDS = Object.freeze(['weapon_ak47', 'weapon_bizon', ...Object.keys(GUNS).filter((n) => n !== 'weapon_ak47' && n !== 'weapon_bizon').sort()]);
// what every stage starts with (and the gun of replays recorded before guns could be bought)
export const DEFAULT_GUN = 'weapon_bizon';
export const LEGACY_GUN = 'weapon_ak47';

export const KNIFE = freezeDeep({
  chassis: 'knife_default_ct', deploy: 1.0,
  slash: { cycle: 0.4, cycle2: 0.4, first: 40, follow: 25, range: 48 },
  stab: { cycle: 1.0, cycle2: 1.0, damage: 65, range: 32 },
});

const ALIAS = new Map();
for (const g of Object.values(GUNS)) for (const a of g.aliases) ALIAS.set(a, g.name);

// What someone typed -> a gun's vdata name, or null: "!bizon", "ak47", "weapon_m4a1", "M4A1-S", "/awp".
export function findGun(text) {
  const t = String(text ?? '').trim().toLowerCase().replace(/^[!/]/, '');
  if (!t || t.length > 40) return null;
  if (t.startsWith('weapon_')) return Object.hasOwn(GUNS, t) ? t : ALIAS.get(t.slice(7)) || null;
  return ALIAS.get(t) || (Object.hasOwn(GUNS, `weapon_${t}`) ? `weapon_${t}` : null);
}

// every word that buys a gun (chat commands): the aliases and the bare class names
export function gunCommandNames(name) {
  const g = GUNS[name];
  return g ? [...new Set([...g.aliases, name.slice(7), name])] : [];
}

// every sound event a gun plays (its shot, draw and reload), to fetch before it is heard
export function gunSounds(name) {
  const g = GUNS[name];
  return g ? [g.fireSound, ...g.drawSounds.map((s) => s[1]), ...g.reloadSounds.map((s) => s[1])] : [];
}
